    if (ev.action === "lecture" || !(ev.with === g.forceWith || (ev.lines || []).some(l => l && l.who === g.forceWith))) continue;
    const sv = surveysOf(s).find(x => x.id === g.survey); if (!sv || !sv.result) { g.saidAt = now; continue; }
