  if (!env.DB || !env.GOOGLE_CLIENT_ID) return json({ error: "surveys are not set up" }, {}, 503);
  const voter = await voterOf(req, env); if (!voter) return json({ error: "please sign in to vote", signIn: true }, {}, 401);
